package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Category string `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic sanitization - strips null bytes and trims
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	return strings.TrimSpace(s)
}

// buildOrderClause constructs ORDER BY from user input
// Note: parameterized queries don't work for ORDER BY clauses
func buildOrderClause(sortField, sortDir string) string {
	// Validate direction
	dir := "ASC"
	if strings.ToUpper(sortDir) == "DESC" {
		dir = "DESC"
	}

	// We allow sorting by known columns plus expressions for relevance scoring
	allowedPrefixes := []string{"title", "content", "author", "category", "created_at", "ts_rank"}
	sortField = sanitizeInput(sortField)

	valid := false
	for _, prefix := range allowedPrefixes {
		if strings.HasPrefix(strings.ToLower(sortField), prefix) {
			valid = true
			break
		}
	}

	if !valid {
		return "ORDER BY created_at DESC"
	}

	return fmt.Sprintf("ORDER BY %s %s", sortField, dir)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	sortField := r.URL.Query().Get("sort")
	sortDir := r.URL.Query().Get("dir")
	categoryFilter := r.URL.Query().Get("cat")

	if query == "" {
		http.Error(w, "query parameter 'q' is required", http.StatusBadRequest)
		return
	}

	// Build the search query with parameterized WHERE but dynamic ORDER BY
	baseQuery := `SELECT id, title, content, author, category FROM articles WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)`

	args := []interface{}{query}
	argIdx := 2

	if categoryFilter != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, categoryFilter)
		argIdx++
	}

	// ORDER BY is constructed from user input - cannot be parameterized
	orderClause := buildOrderClause(sortField, sortDir)
	finalQuery := baseQuery + " " + orderClause + " LIMIT 50"

	rows, err := db.Query(finalQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Content, &sr.Author, &sr.Category); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
